93	// listenReusable creates a new listener for the given network and address, and adds it to listenerPool.
94	func listenReusable(ctx context.Context, lnKey string, network, address string, config net.ListenConfig) (any, error) {
95		// even though SO_REUSEPORT lets us bind the socket multiple times,
96		// we still put it in the listenerPool so we can count how many
97		// configs are using this socket; necessary to ensure we can know
98		// whether to enforce shutdown delays, for example (see #5393).
99		var (
100			ln         io.Closer
101			err        error
102			socketFile *os.File
103		)
104	
105		fd := slices.Contains([]string{"fd", "fdgram"}, network)
106		if fd {
107			socketFd, err := strconv.ParseUint(address, 0, strconv.IntSize)
108			if err != nil {
109				return nil, fmt.Errorf("invalid file descriptor: %v", err)
110			}
111	
112			func() {
113				socketFilesMu.Lock()
114				defer socketFilesMu.Unlock()
115	
116				socketFdWide := uintptr(socketFd)
117				var ok bool
118	
119				socketFile, ok = socketFiles[socketFdWide]
120	
121				if !ok {
122					socketFile = os.NewFile(socketFdWide, lnKey)
123					if socketFile != nil {
124						socketFiles[socketFdWide] = socketFile
125					}
126				}
127			}()
128	
129			if socketFile == nil {
130				return nil, fmt.Errorf("invalid socket file descriptor: %d", socketFd)
131			}
132		} else {
133			// wrap any Control function set by the user so we can also add our reusePort control without clobbering theirs
134			oldControl := config.Control
135			config.Control = func(network, address string, c syscall.RawConn) error {
136				if oldControl != nil {
137					if err := oldControl(network, address, c); err != nil {
138						return err
139					}
140				}
141				return reusePort(network, address, c)
142			}
143		}
144	
145		datagram := slices.Contains([]string{"udp", "udp4", "udp6", "unixgram", "fdgram"}, network)
146		if datagram {
147			if fd {
148				ln, err = net.FilePacketConn(socketFile)
149			} else {
150				ln, err = config.ListenPacket(ctx, network, address)
151			}
152		} else {
153			if fd {
154				ln, err = net.FileListener(socketFile)
155			} else {
156				ln, err = config.Listen(ctx, network, address)
157			}
158		}
159	
160		if err == nil {
161			listenerPool.LoadOrStore(lnKey, nil)
162		}
163	
164		if datagram {
165			if !fd {
166				// TODO: Not 100% sure this is necessary, but we do this for net.UnixListener, so...
167				if unix, ok := ln.(*net.UnixConn); ok {
168					cnt := new(atomic.Int32)
169					cnt.Store(1)
170					ln = &unixConn{unix, lnKey, cnt}
171					unixSockets[lnKey] = ln.(*unixConn)
172				}
173			}
174			// lightly wrap the connection so that when it is closed,
175			// we can decrement the usage pool counter
176			if specificLn, ok := ln.(net.PacketConn); ok {
177				ln = deletePacketConn{specificLn, lnKey}
178			}
179		} else {
180			if !fd {
181				// if new listener is a unix socket, make sure we can reuse it later
182				// (we do our own "unlink on close" -- not required, but more tidy)
183				if unix, ok := ln.(*net.UnixListener); ok {
184					unix.SetUnlinkOnClose(false)
185					cnt := new(atomic.Int32)
186					cnt.Store(1)
187					ln = &unixListener{unix, lnKey, cnt}
188					unixSockets[lnKey] = ln.(*unixListener)
189				}
190			}
191			// lightly wrap the listener so that when it is closed,
192			// we can decrement the usage pool counter
193			if specificLn, ok := ln.(net.Listener); ok {
194				ln = deleteListener{specificLn, lnKey}
195			}
196		}
197	
198		// other types, I guess we just return them directly
199		return ln, err
200	}
