224	func (uln *unixListener) Close() error {
225		newCount := uln.count.Add(-1)
226		if newCount == 0 {
227			file, err := uln.File()
228			var name string
229			if err == nil {
230				name = file.Name()
231			}
232			defer func() {
233				unixSocketsMu.Lock()
234				delete(unixSockets, uln.mapKey)
235				unixSocketsMu.Unlock()
236				if err == nil {
237					_ = syscall.Unlink(name)
238				}
239			}()
240		}
241		return uln.UnixListener.Close()
242	}
