375			defer r.Body.Close()
376			bytes, err := io.ReadAll(r.Body)
377			if err != nil {
378				t.Fatalf("unable to read the response body %s", err)
379			}
380	
381			n := len(bytes)
382	
383			var writer io.Writer
384			if strings.Contains(r.Header.Get("Accept-Encoding"), "gzip") {
385				gw, err := gzip.NewWriterLevel(w, 5)
386				if err != nil {
387					t.Error("can't return gzip data")
388					w.WriteHeader(http.StatusInternalServerError)
389					return
390				}
391				defer gw.Close()
392				writer = gw
393				w.Header().Set("Content-Encoding", "gzip")
394				w.Header().Del("Content-Length")
395				w.WriteHeader(200)
396			} else {
397				writer = w
398			}
399			if n > 0 {
400				writer.Write(bytes[:])
401			}
402		})
403	
404		server := &http.Server{
405			Addr:    "127.0.0.1:54321",
406			Handler: handler,
407		}
408		return server
409	}
410	
411	// GenerateRandomBytes returns securely generated random bytes.
412	// It will return an error if the system's secure random
413	// number generator fails to function correctly, in which
414	// case the caller should not continue.
415	func GenerateRandomBytes(n int) ([]byte, error) {
416		b := make([]byte, n)
417		_, err := rand.Read(b)
418		// Note that err == nil only if we read len(b) bytes.
419		if err != nil {
420			return nil, err
421		}
422	
423		return b, nil
424	}
425	
426	// GenerateRandomString returns a securely generated random string.
427	// It will return an error if the system's secure random
428	// number generator fails to function correctly, in which
429	// case the caller should not continue.
430	func GenerateRandomString(n int) (string, error) {
431		const letters = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-"
432		bytes, err := GenerateRandomBytes(n)
433		if err != nil {
434			return "", err
435		}
436		for i, b := range bytes {
437			bytes[i] = letters[b%byte(len(letters))]
438		}
439		return string(bytes), nil
440	}
